(() => {
  'use strict';
  let KEY='carteira_codex_v1';
  const AUTO='/backup_carteira_diversificacao.json';
  const labels={equities:'Ações',fiis:'FIIs',etfs:'ETFs',cash_or_fixed_income:'Renda fixa / caixinha',treasury_direct:'Tesouro Direto',other:'Outros'};
  const snapshotLabels={reported:'Relato histórico do Investidor10',reported_pre_contribution:'Antes do aporte',reported_after_contribution:'Após o aporte',official_friday_close:'Fechamento de sexta confirmado pelo usuário',raw_reported_weekend_value:'Observação bruta em fim de semana',raw_weekend_app_observation:'Observação bruta do app em fim de semana',raw_market_holiday_observation:'Observação bruta em feriado',weekend_neutral_chart_point:'Ponto neutro do gráfico'};
  const pageNames={dashboard:'Visão geral',portfolio:'Carteira',daily:'Acompanhamento diário',analysis:'Análise de ativos',dividends:'Proventos',planner:'Planejamento de aportes',history:'Histórico',sources:'Fontes e configurações'};
  const read=()=>{try{return JSON.parse(localStorage.getItem(KEY)||'null')}catch{return null}};
  const emptyState=()=>({schema_version:'1.0.0',assets:[],transactions:[],quotes:[],snapshots:[],dividends:[],plans:[],fixedIncome:[],fixedIncomeObservations:[],dailyMarketSnapshots:[],marketCaptureReports:[],historicalSnapshots:[],sourceLogs:[],research:[],settings:{monthlyBase:750,goals:[10000,50],timezone:'America/Maceio'},pendingPlan:null,importedFiles:[]});
  const legacyLocalState=read();let activeUser=null;let state=legacyLocalState||emptyState();
  function mergeLocalOnly(shared,local){const merged={...local,...shared};for(const key of ['assets','transactions','quotes','snapshots','dividends','plans','fixedIncome','fixedIncomeObservations','dailyMarketSnapshots','marketCaptureReports','historicalSnapshots','dailyReportRecords','sourceLogs','research','portfolioAllocationSnapshots','dailyAssetImpacts','contributionHistory','withinClassWeights','positionHistory','importedRules','importReports','rawHistoryImports']){const primary=Array.isArray(shared[key])?shared[key]:[],secondary=Array.isArray(local[key])?local[key]:[],idFor=row=>key==='assets'?String(row.ticker||row.id):String(row.id||`${row.date||''}|${row.ticker||''}|${row.competence||''}`),seen=new Set(primary.map(idFor));merged[key]=[...primary,...secondary.filter(row=>!seen.has(idFor(row)))];}merged.importedFiles=[...new Set([...(shared.importedFiles||[]),...(local.importedFiles||[])])];merged.settings={...(local.settings||{}),...(shared.settings||{})};merged.pendingPlan=shared.pendingPlan??local.pendingPlan??null;return merged}
  let sharedSyncReady=false, sharedSyncQueue=Promise.resolve();
  let dashboardPeriod='all', transactionCompetence='all', dividendMonth='auto';
  const save=()=>{const payload=JSON.stringify(state);localStorage.setItem(KEY,payload);if(sharedSyncReady)sharedSyncQueue=sharedSyncQueue.then(()=>window.FirebaseCloud?.enabled?FirebaseCloud.putState(state):fetch('/api/state',{method:'PUT',headers:{'Content-Type':'application/json'},body:payload})).then(r=>{if(r instanceof Response&&!r.ok)throw Error(`HTTP ${r.status}`)}).catch(err=>console.error('Falha ao sincronizar os dados compartilhados:',err));};
  const fmt=n=>n==null?'Não disponível':Number(n).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
  const fmtUnit=n=>n==null?'Não disponível':`R$ ${Number(n).toLocaleString('pt-BR',{minimumFractionDigits:Number(n)<0.1?3:2,maximumFractionDigits:6})}`;
  const num=(n,d=2)=>n==null?'—':Number(n).toLocaleString('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d});
  const date=d=>d?new Date(d+'T12:00:00').toLocaleDateString('pt-BR'):'Data não informada';
  const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Maceio'}).format(new Date());
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const safeUrl=s=>{try{const u=new URL(s);return ['https:','http:'].includes(u.protocol)?u.href:null}catch{return null}};
  const total=(arr,key)=>arr.reduce((s,x)=>s+(Number(x[key])||0),0);
  function importBackup(data, filename='backup_carteira_diversificacao.json'){
    if(!data||!data.schema_version)throw Error('Arquivo inválido: schema_version não encontrado.');
    if(data.dataset==='historico_patrimonio_outubro_2026_desde_18'){const result=PortfolioCore.importRecentPortfolioHistory(data,state,filename);state=result.state;state.sourceLogs.push({provider:filename,url:'arquivo local',at:new Date().toISOString(),status:'Histórico diário importado',detail:`${result.report.importedTotal} registros importados e ${result.report.duplicatesTotal} equivalentes/duplicados ignorados.`});save();return result.report}
    if(data.record_type==='market_capture'){const result=PortfolioCore.importMarketCapture(data,state,filename);state=result.state;state.importedFiles=[...new Set([...(state.importedFiles||[]),filename])];save();return result.report}
    if(Array.isArray(data.patrimonio_history)&&Array.isArray(data.transactions)){
      const result=PortfolioCore.importInvestmentHistory(data,state,filename);state=result.state;const report=result.report;
      state.sourceLogs.push({provider:filename,url:'arquivo local',at:new Date().toISOString(),status:'Histórico importado',detail:`${report.importedTotal} registros históricos importados e ${report.duplicatesTotal} equivalentes/duplicados ignorados.`});save();return report;
    }
    if(data.backup_type==='portfolio_full_backup'&&Array.isArray(data.assets)){
      const merged=(oldRows,newRows,key)=>{const map=new Map(oldRows.map(x=>[String(x[key]),x]));newRows.forEach(x=>{const k=String(x[key]);if(map.has(k))map.set(k,{...map.get(k),...x});else map.set(k,x)});return [...map.values()]};
      state.assets=merged(state.assets,data.assets,'ticker');for(const k of ['transactions','quotes','snapshots','dividends','plans','fixedIncome','fixedIncomeObservations','dailyMarketSnapshots','marketCaptureReports','historicalSnapshots','dailyReportRecords','sourceLogs','research','portfolioAllocationSnapshots','dailyAssetImpacts','contributionHistory','withinClassWeights','positionHistory','importedRules','importReports','rawHistoryImports'])if(Array.isArray(data[k]))state[k]=merged(state[k],data[k],'id');
      state.settings={...state.settings,...data.settings};state.pendingPlan=state.pendingPlan||data.pendingPlan||null;state.importedFiles=[...new Set([...(state.importedFiles||[]),filename])];save();return;
    }
    if(!Array.isArray(data.positions_as_of_2026_09_11))throw Error('Arquivo de posições inválido.');
    const known=new Set(state.assets.map(a=>a.ticker.toUpperCase()));
    data.positions_as_of_2026_09_11.forEach(p=>{const t=String(p.ticker||'').trim();if(!t||!Number.isFinite(Number(p.quantity))||Number(p.quantity)<0)throw Error('Posição inválida no arquivo.');if(!known.has(t.toUpperCase()))state.assets.push({id:'asset-'+t.toUpperCase(),ticker:t,name:t,asset_type:p.asset_type,asset_class:p.asset_class,quantity:Number(p.quantity),position_date:p.position_date,average_cost_brl:p.average_cost_brl??null,current_price_brl:p.current_price_brl??null,quote:null,data_status:p.data_status,preferred_quote_source:p.preferred_quote_source||'Investidor10',origin:'importado'});});
    state.settings={...state.settings,monthlyBase:Number(data.settings?.monthly_base_contribution_brl)||750,goals:(data.settings?.goals||[]).map(g=>g.target_brl),timezone:data.timezone||'America/Maceio',dailyTracking:data.settings?.daily_tracking||{},monthlyMethod:data.settings?.monthly_contribution_method||{}};
    state.fixedIncome=data.fixed_income_balance_references||[];state.historicalSnapshots=data.historical_aggregate_snapshots||[];state.pendingPlan=(data.monthly_plan_references||[]).find(p=>p.plan_status?.includes('pending'))||null;
    state.dividends=(data.dividend_references||[]).map(d=>({id:'ref-'+d.competence+'-'+d.status,competence:d.competence,forecast:d.reported_forecast_brl??null,received:d.reported_received_brl??null,status:d.status,source:d.source,note:d.note,reference:true}));
    state.sourceLogs.push({provider:filename,url:'arquivo local',at:new Date().toISOString(),status:'Importado',detail:`${data.positions_as_of_2026_09_11.length} posições; importação idempotente`});state.importedFiles=[...new Set([...state.importedFiles,filename])];save();
  }
  function allClassValues(){let result={};state.assets.forEach(a=>{let q=latestQuote(a);if(q&&Number.isFinite(Number(q.price)))result[a.asset_class]=(result[a.asset_class]||0)+a.quantity*Number(q.price)});return result}
  function latestQuote(a){return a.quote||null}
  const isConfirmedSnapshot=s=>s.validationStatus==='user_confirmed_close'||s.status==='confirmed'||s.status==='weekend_explicitly_confirmed';
  function latestSnapshot(){return [...state.snapshots].filter(isConfirmedSnapshot).sort((a,b)=>b.date.localeCompare(a.date))[0]||null}
  function planBudget(month){const p=state.plans.find(x=>x.month===month);const prev=state.plans.find(x=>x.month===previousMonth(month));const eligible=total(state.dividends.filter(d=>d.status==='received'&&d.destined&&d.competence===previousMonth(month)),'received');return {base:Number(state.settings.monthlyBase)||0,dividends:eligible,surplus:Number(prev?.surplusFinal)||0,confirmedCash:Number(p?.confirmedCash)||0,total:PortfolioCore.budget(state.settings.monthlyBase,eligible,Number(prev?.surplusFinal)||0)}}
  function previousMonth(m){let [y,mo]=m.split('-').map(Number);return mo===1?`${y-1}-12`:`${y}-${String(mo-1).padStart(2,'0')}`}
  function cashPlan(){return planBudget(today().slice(0,7))}
  function weightPosition(a){const vals=allClassValues(), denom=Object.values(vals).reduce((x,y)=>x+y,0);return denom?100*a.quantity*latestQuote(a).price/denom:null}
  function renderLogin(error=''){
    document.body.classList.add('auth-required');
    document.getElementById('app').innerHTML=`<div class="login-shell"><form id="login-form" class="login-card"><div class="brand-mark">C</div><div class="eyebrow">CONTROLE DE CARTEIRA</div><h1>${activeUser?'Trocar perfil':'Entrar na carteira'}</h1><p>${activeUser?'Digite o perfil e a senha da carteira que deseja acessar.':'Digite seu perfil e sua senha para acessar sua carteira individual.'}</p><div class="field"><label for="login-username">Perfil</label><input id="login-username" name="username" type="text" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="Digite seu perfil" required autofocus></div><div class="field"><label for="login-password">Senha</label><input id="login-password" name="password" type="password" autocomplete="current-password" required></div><div class="login-error" role="alert">${esc(error)}</div><button class="btn btn-primary" type="submit">Entrar</button></form></div>`;
    const form=document.getElementById('login-form');form.addEventListener('submit',async e=>{e.preventDefault();const button=form.querySelector('button[type="submit"]');button.disabled=true;try{await sharedSyncQueue;let user;if(window.FirebaseCloud?.enabled){user=await FirebaseCloud.login(form.elements.username.value,form.elements.password.value)}else{const response=await fetch('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:form.elements.username.value,password:form.elements.password.value})});const result=await response.json();if(!response.ok)throw Error(result.error||'Não foi possível entrar.');user=result.user}await activateUser(user)}catch(err){button.disabled=false;form.querySelector('.login-error').textContent=err.message;form.elements.password.value='';form.elements.password.focus()}});
  }
  function openProfileSwitcher(){
    dialog('Trocar perfil',`<div class="field"><label for="switch-username">Perfil de destino</label><input id="switch-username" name="username" type="text" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="Digite o perfil" required></div><div class="field"><label>Senha do perfil</label><input name="password" type="password" autocomplete="current-password" required></div><div class="login-error" role="alert"></div><div class="small">Cada perfil abre uma carteira e um banco de dados separados.</div>`,()=>false,'Acessar perfil');
    const d=document.getElementById('dialog'),form=d.querySelector('form');form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('button[type="submit"]');button.disabled=true;try{await sharedSyncQueue;let user;if(window.FirebaseCloud?.enabled){user=await FirebaseCloud.login(form.elements.username.value,form.elements.password.value)}else{const response=await fetch('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:form.elements.username.value,password:form.elements.password.value})});const result=await response.json();if(!response.ok)throw Error(result.error||'Perfil ou senha incorretos.');user=result.user}d.close();await activateUser(user)}catch(err){form.querySelector('.login-error').textContent=err.message;form.elements.password.value='';button.disabled=false;form.elements.password.focus()}};
  }
  async function activateUser(user){
    activeUser=user;KEY=`carteira_codex_v1:${user.id}`;document.body.classList.remove('auth-required');sharedSyncReady=false;
    const scopedLocal=read();state=scopedLocal||(user.id==='vitor-samuel'?legacyLocalState:null)||emptyState();
    let payload;if(window.FirebaseCloud?.enabled){payload=await FirebaseCloud.getState()}else{const response=await fetch('/api/state');if(!response.ok)throw Error('Não foi possível carregar a carteira deste perfil.');payload=await response.json()}state=mergeLocalOnly(payload.state||emptyState(),state);sharedSyncReady=true;
    const profileButton=document.getElementById('profile-button');profileButton.textContent=user.name.slice(0,1).toLocaleUpperCase('pt-BR');profileButton.title=`Perfil: ${user.name} · trocar perfil`;render();save();
  }
  function pageHead(title,desc,actions=''){return `<div class="page-head"><div><div class="eyebrow">ESPAÇO PESSOAL　/　${esc(title.toUpperCase())}</div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`}
  function notice(text,type=''){return `<div class="notice ${type}"><span>ⓘ</span><div>${text}</div></div>`}
  const pendingCount=()=>state.assets.filter(a=>!a.quote||!a.average_cost_brl).length+(state.fixedIncome||[]).length+(state.pendingPlan?1:0);
  function renderDashboard(){const snap=latestSnapshot(), prev=[...state.snapshots].filter(s=>snap&&s.date<snap.date&&isConfirmedSnapshot(s)).sort((a,b)=>b.date.localeCompare(a.date))[0], vals=allClassValues(), invest=Object.values(vals).reduce((a,b)=>a+b,0), diff=snap&&prev?snap.total-prev.total:null, pReceived=total(state.dividends.filter(x=>x.competence===today().slice(0,7)&&x.status==='received'),'received');
    const cls=Object.entries(vals).map(([k,v])=>`<div class="allocation-row"><span>${labels[k]||k}</span><div class="track"><i style="width:${invest?Math.max(2,v/invest*100):0}%"></i></div><b>${invest?num(v/invest*100,1)+'%':'—'}</b></div>`).join('')||'<div class="empty">Registre preços com fonte e data para visualizar a composição.</div>';
    const monthlyMap=new Map();[...state.snapshots].filter(s=>s.chartVisible!==false&&!s.isNeutral&&!String(s.status||'').includes('weekend_neutral')&&s.total!=null).sort((a,b)=>a.date.localeCompare(b.date)).forEach(s=>monthlyMap.set(s.date.slice(0,7),s));
    const allSeries=[...monthlyMap.entries()].map(([month,snapshot])=>({month,snapshot}));const newestMonth=allSeries.at(-1)?.month;const monthCount={3:3,6:6,12:12}[dashboardPeriod];const cutoffMonth=monthCount&&newestMonth?(()=>{const [y,m]=newestMonth.split('-').map(Number);const d=new Date(y,m-1-(monthCount-1),1);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`})():null;const series=cutoffMonth?allSeries.filter(x=>x.month>=cutoffMonth):allSeries;
    const historical=[...(state.historicalSnapshots||[])].filter(x=>x.total_invested_brl!=null&&x.total_portfolio_value_brl!=null).sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')))[0];
    const basis=historical||[...state.snapshots].filter(s=>s.invested!=null).sort((a,b)=>b.date.localeCompare(a.date))[0];const contributed=historical?Number(historical.total_invested_brl):basis?.invested;const currentValue=historical?Number(historical.total_portfolio_value_brl):basis?.total;const investmentGap=contributed==null||currentValue==null?null:currentValue-contributed;
    const first=series[0]?.snapshot,last=series.at(-1)?.snapshot,periodDelta=series.length>1?Number(last.chartValue??last.total)-Number(first.chartValue??first.total):null;const periodPct=periodDelta!=null&&Number(first.chartValue??first.total)!==0?periodDelta/Number(first.chartValue??first.total)*100:null;
    const chartMax=Math.max(...series.map(x=>Number(x.snapshot.chartValue??x.snapshot.total)),1);const monthlyChart=series.map(({month,snapshot})=>`<div class="monthly-bar-item" title="${esc(date(snapshot.date))} · ${esc(snapshot.status||'registrado')} · ${fmt(snapshot.chartValue??snapshot.total)}"><b>${fmt(snapshot.chartValue??snapshot.total)}</b><i style="height:${Math.max(8,Number(snapshot.chartValue??snapshot.total)/chartMax*100)}%"></i><span>${month.slice(5,7)}/${month.slice(0,4)}</span></div>`).join('');
    const seriesRows=[...series].reverse().map(({month,snapshot:s})=>`<tr><td>${esc(month)}<span class="subcell">fechamento selecionado · ${date(s.date)}</span></td><td>${fmt(s.chartValue??s.total)}${['user_reported_daily_snapshot','reported'].includes(s.status)?'<span class="subcell">informado, não fechamento confirmado</span>':''}</td><td>${fmt(s.invested??null)}</td><td>${s.invested!=null?fmt(Number(s.chartValue??s.total)-Number(s.invested)):'Não disponível'}</td><td>${esc(s.status||'registrado')}</td></tr>`).join('');
    return `${pageHead('Visão geral','Acompanhe seu patrimônio, a composição e os dados que precisam de conferência.',`<button class="btn btn-outline" data-action="snapshot">＋ Registrar patrimônio</button>`)}${pendingCount()?notice(`<strong>${pendingCount()} itens precisam de atenção.</strong> Alguns preços, custos médios e saldos ainda precisam de conferência. Dados transcritos de prints são reportados, não verificados automaticamente.`):''}<div class="grid metrics"><div class="card"><div class="metric-label">Último fechamento confirmado</div><div class="metric-value">${snap?fmt(snap.total):'Não disponível'}</div><div class="metric-foot">${snap?`${date(snap.date)} · ${esc(snap.origin||'Registro manual')}`:'Registre um snapshot para iniciar o acompanhamento.'}</div></div><div class="card"><div class="metric-label">Variação do último registro</div><div class="metric-value ${diff>0?'positive':diff<0?'negative':''}">${diff==null?'Não disponível':fmt(diff)}</div><div class="metric-foot">${diff==null?'São necessários dois snapshots comparáveis.':`Comparado com ${date(prev.date)} · ${prev.total?num(diff/prev.total*100,2)+'%':'percentual indisponível'}`}</div></div><div class="card"><div class="metric-label">Valor de mercado cotado</div><div class="metric-value">${invest?fmt(invest):'Não disponível'}</div><div class="metric-foot">Soma posições com preços registrados; valores de prints são reportados.</div></div><div class="card"><div class="metric-label">Proventos recebidos neste mês</div><div class="metric-value">${pReceived?fmt(pReceived):fmt(0)}</div><div class="metric-foot">Recebidos e confirmados; previsão fica separada.</div></div></div><div class="grid metrics" style="margin-top:14px"><div class="card"><div class="metric-label">Valor informado como investido</div><div class="metric-value">${fmt(contributed)}</div><div class="metric-foot">${basis?`${date(historical?.date||basis.date)} · informado no Investidor10`:'Sem valor de aporte acumulado registrado.'}</div></div><div class="card"><div class="metric-label">Patrimônio na mesma referência</div><div class="metric-value">${fmt(currentValue)}</div><div class="metric-foot">Valor de captura/histórico, não fechamento independente.</div></div><div class="card"><div class="metric-label">Diferença aritmética</div><div class="metric-value ${investmentGap>0?'positive':investmentGap<0?'negative':''}">${fmt(investmentGap)}</div><div class="metric-foot">Patrimônio menos valor informado como investido; não é rentabilidade conciliada.</div></div><div class="card"><div class="metric-label">Lucro exibido pela fonte</div><div class="metric-value">${fmt(historical?.profit_total_displayed_brl??null)}</div><div class="metric-foot">Mantido separado; a fonte reportou números que não conciliam por R$ ${historical?num(Math.abs(Number(historical.profit_total_displayed_brl||0)-Number(investmentGap||0))):'—'}.</div></div></div><div class="grid dashboard-grid"><div class="card"><div class="card-heading"><div><h2>Evolução do patrimônio</h2><p>Patrimônio, valor investido e diferença por registro</p></div><select id="dashboard-period" aria-label="Período da evolução mensal"><option value="3" ${dashboardPeriod==='3'?'selected':''}>3 meses</option><option value="6" ${dashboardPeriod==='6'?'selected':''}>6 meses</option><option value="12" ${dashboardPeriod==='12'?'selected':''}>12 meses</option><option value="all" ${dashboardPeriod==='all'?'selected':''}>Todo o histórico</option></select></div><div class="split"><span>Variação entre o primeiro e o último mês</span><b class="${periodDelta>0?'positive':periodDelta<0?'negative':''}">${periodDelta==null?'Não disponível':`${fmt(periodDelta)} · ${periodPct==null?'—':num(periodPct,2)+'%'}`}</b></div><div class="monthly-chart" role="img" aria-label="Evolução mensal do patrimônio; barras exibem valores registrados">${monthlyChart||'<div class="empty">Sem fechamentos mensais para exibir.</div>'}</div><div class="table-wrap"><table><thead><tr><th>Mês / referência</th><th>Patrimônio registrado</th><th>Valor investido informado</th><th>Diferença</th><th>Origem/status</th></tr></thead><tbody>${seriesRows||'<tr><td colspan="5" class="empty">Nenhum registro neste período.</td></tr>'}</tbody></table></div><p class="small">O gráfico usa o último registro não neutro disponível em cada mês. Valores investidos só aparecem quando informados; meses sem fechamento não são interpolados.</p></div><div class="card"><div class="card-heading"><div><h2>Alocação cotada por classe</h2><p>Denominador: posições com cotação confirmada</p></div><span class="pill">BRL</span></div><div class="allocation-list">${cls}</div></div></div><div class="grid two-col"><div class="card"><div class="card-heading"><div><h2>Metas</h2><p>Progresso calculado apenas sobre patrimônio registrado</p></div></div><div class="split"><span>Patrimônio · meta ${fmt(state.settings.goals?.[0]||10000)}</span><b>${snap?num(snap.total/(state.settings.goals?.[0]||10000)*100,1)+'%':'—'}</b></div><div class="progress"><i style="width:${snap?Math.min(100,snap.total/(state.settings.goals?.[0]||10000)*100):0}%"></i></div><div class="small">${snap?`${fmt(snap.total)} de ${fmt(state.settings.goals?.[0]||10000)}`:'Registre um snapshot para acompanhar.'}</div></div><div class="card"><div class="card-heading"><div><h2>Próximas ações</h2><p>Itens ainda não conciliados</p></div></div><div class="ref-item">${state.assets.filter(a=>!a.quote).length} cotações de ativos aguardam registro e fonte.</div><div class="ref-item">${state.fixedIncome.length} saldos históricos precisam de confirmação atual.</div><div class="ref-item">${state.pendingPlan?'Plano de outubro/2026 pendente de confirmação de execução.':'Nenhum plano de compras pendente.'}</div></div></div>`}
  function assetRows(arr=state.assets){return arr.map(a=>{const q=latestQuote(a),mv=q?PortfolioCore.marketValue(a.quantity,q.price):null,w=weightPosition(a),quoteLabel=q?.status==='user_reported_screenshot'?'Informado no print':q?'Manual informado':'Pendente';return `<tr><td><span class="asset-icon">${esc(a.ticker.slice(0,2))}</span><span class="ticker">${esc(a.ticker)}</span><span class="subcell">${esc(labels[a.asset_class]||a.asset_class)}</span></td><td>${num(a.quantity,Number.isInteger(Number(a.quantity))?0:4)}</td><td>${q?fmt(q.price):'Não disponível'}<span class="subcell">${q?`${esc(q.source)} · ${date(q.referenceDate)}`:'Precisa de confirmação'}</span></td><td>${mv==null?'Não disponível':fmt(mv)}</td><td>${a.average_cost_brl==null?'Não informado':fmt(a.average_cost_brl)}</td><td>${w==null?'—':num(w,1)+'%'}</td><td><span class="status ${q&&q.status!=='user_reported_screenshot'?'ok':''}">${quoteLabel}</span></td><td><button class="btn btn-light" data-action="edit-asset" data-id="${esc(a.id)}">Abrir</button></td></tr>`}).join('')}
  function renderPortfolio(){return `${pageHead('Carteira','Posições e movimentações; históricos mantêm os preços efetivamente informados.',`<button class="btn btn-outline" data-action="add-asset">＋ Ativo</button><button class="btn btn-primary" data-action="add-transaction">＋ Movimentação</button>`)}${notice('As quantidades permanecem separadas das cotações. Dados transcritos de prints são identificados como informados pelo usuário e guardam a data de captura quando a tela não mostra o período da cotação.','info')}<div class="card table-card"><div class="table-top"><div><b class="section-title">Posições</b><div class="small">${state.assets.length} ativos · cotação e custo mantidos separados da quantidade</div></div><input id="asset-search" placeholder="Buscar ativo" aria-label="Buscar ativo" style="max-width:180px;padding:9px;border:1px solid #e1e7e3;border-radius:7px"></div><div class="table-wrap"><table><thead><tr><th>Ativo / classe</th><th>Quantidade</th><th>Cotação usada</th><th>Valor de mercado</th><th>Custo médio</th><th>Peso cotado</th><th>Status</th><th></th></tr></thead><tbody id="asset-rows">${assetRows()}</tbody></table>${state.assets.length?'':'<div class="empty">Nenhum ativo. Importe um backup ou adicione uma posição.</div>'}</div></div><div class="small" style="margin-top:12px">O peso usa somente as posições com cotação registrada. Caixa e renda fixa informados mas não confirmados ficam fora desse cálculo.</div><div class="card table-card" style="margin-top:16px"><div class="table-top"><div><b class="section-title">Movimentações</b><div class="small">Compras históricas importadas e operações registradas.</div></div><label class="field-inline">Competência <select id="transaction-competence"><option value="all">Todas</option>${[...new Set(state.transactions.map(t=>String(t.date||'').slice(0,7)).filter(Boolean))].sort().reverse().map(m=>`<option value="${m}" ${transactionCompetence===m?'selected':''}>${m}</option>`).join('')}</select></label></div><div class="small" style="margin:0 16px 10px">${state.transactions.filter(t=>transactionCompetence==='all'||String(t.date||'').startsWith(transactionCompetence)).length} movimentações na seleção.</div><div class="table-wrap"><table><thead><tr><th>Data</th><th>Ativo</th><th>Tipo / status</th><th>Quantidade</th><th>Preço unitário</th><th>Total registrado</th><th>Origem</th></tr></thead><tbody>${[...state.transactions].filter(t=>transactionCompetence==='all'||String(t.date||'').startsWith(transactionCompetence)).sort((a,b)=>String(b.date).localeCompare(String(a.date))).map(t=>`<tr><td>${date(t.date)}</td><td class="ticker">${esc(t.ticker||t.asset)}</td><td>${esc(t.type)}<span class="subcell">${esc(t.status|| (t.confirmed?'confirmada':'não confirmada'))}</span></td><td>${num(t.quantity,0)}</td><td>${fmt(t.price??t.unit_price_brl??null)}</td><td>${fmt(t.total_brl??(t.price!=null?t.price*t.quantity:null))}</td><td>${esc(t.source||'Não informada')}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">Nenhuma movimentação registrada.</td></tr>'}</tbody></table></div></div>`}
  function renderMissingDaily(){return (state.dailyReportRecords||[]).filter(r=>r.record_type==='missing'||r.rawRecord?.patrimonio_total==null).map(r=>`<div class="card" style="margin-top:12px"><b>Sem fechamento confirmado · ${date(r.date)}</b><div class="small">${esc(r.rawRecord?.notes||'Valor ausente; não interpolado.')}</div></div>`).join('')}
  function renderDaily(){const sorted=[...state.snapshots].sort((a,b)=>b.date.localeCompare(a.date)),captures=[...(state.dailyMarketSnapshots||[])].sort((a,b)=>String(b.captured_at).localeCompare(String(a.captured_at)));return `${pageHead('Acompanhamento diário','Cotações e observações diárias mantêm fonte, horário, status e histórico.',`<button class="btn btn-primary" data-action="snapshot">＋ Novo snapshot</button>`)}${notice('Os pontos neutros repetem explicitamente o último fechamento para visualização. Prints são registros informados pelo usuário: a data visível na fonte e os componentes não conciliados permanecem sinalizados.','info')}${captures.map(c=>`<div class="card table-card" style="margin-bottom:16px"><div class="table-top"><div><b class="section-title">Captura de mercado · ${date(c.reference_date)}</b><div class="small">${esc(c.source)} · recebido em ${new Date(c.captured_at).toLocaleString('pt-BR',{timeZone:state.settings.timezone||'America/Maceio'})} · data da tela não visível · <a href="${esc(c.source_url)}" target="_blank" rel="noopener">fonte</a>${c.source_image?` · imagem arquivada: ${esc(c.source_image)}`:''}</div></div><span class="pill">Informado no print</span></div><div class="table-wrap"><table><thead><tr><th>Ativo / classe</th><th>Qtd.</th><th>Custo médio informado</th><th>Preço atual exibido</th><th>Saldo exibido</th><th>Proventos recebidos exibidos</th></tr></thead><tbody>${(c.positions||[]).map(p=>`<tr><td class="ticker">${esc(p.ticker)}<span class="subcell">${esc(labels[p.asset_class]||p.asset_class)}</span></td><td>${num(p.quantity,p.quantity%1?4:0)}</td><td>${fmt(p.average_cost_brl??null)}</td><td>${fmt(p.current_price_brl)}</td><td>${fmt(p.reported_market_value_brl??Number(p.quantity)*Number(p.current_price_brl))}</td><td>${p.cumulative_dividends_reported_brl==null?'—':`${fmt(p.cumulative_dividends_reported_brl)} · acumulado sem competência`}</td></tr>`).join('')}</tbody></table></div>${c.fixed_income?`<div class="ref-item"><b>Renda fixa · ${esc(c.fixed_income.asset)}</b><div class="small">Aplicado ${fmt(c.fixed_income.invested_brl)} · saldo exibido ${fmt(c.fixed_income.balance_brl)} · não confirmado como saldo atual.</div></div>`:''}<div class="ref-item"><b>Subtotais por classe exibidos</b><div class="small">${Object.entries(c.class_totals_brl||{}).map(([k,v])=>`${esc(labels[k]||k)}: ${fmt(v)}`).join(' · ')||'Não informado'}</div></div>${[...(c.report?.conflicts||[]),...(c.report?.inconsistencies||[])].map(x=>`<div class="small">⚠ ${esc(x)}</div>`).join('')}<div class="small">${c.portfolio_total_brl==null?'Total geral não informado na parte visível do print; não calculado como patrimônio confirmado.':''}</div></div>`).join('')}<div class="card table-card"><div class="table-top"><div><b class="section-title">Snapshots e observações de patrimônio</b><div class="small">Valores originais, status e referência gráfica são preservados separadamente.</div></div></div><div class="table-wrap"><table><thead><tr><th>Data</th><th>Valor bruto informado</th><th>Ponto no gráfico</th><th>Variação reportada</th><th>Origem / status</th><th>Notas</th></tr></thead><tbody>${sorted.map((s,i)=>{const prev=sorted.slice(i+1).find(x=>!['neutral_chart_point','raw_app_observation'].includes(x.validationStatus));const d=s.dailyChange??(prev&&!['neutral_chart_point','raw_app_observation'].includes(s.validationStatus)?s.total-prev.total:null);const weekend=PortfolioCore.isWeekend(s.date);return `<tr><td>${date(s.date)}${weekend?'<span class="subcell">Fim de semana</span>':''}</td><td class="ticker">${fmt(s.rawTotal??s.total)}</td><td>${s.chartValue==null?'—':fmt(s.chartValue)}${s.chartVisible===false?'<span class="subcell">Não incluído na série oficial</span>':''}</td><td class="${d>0?'positive':'negative'}">${d==null?'—':fmt(d)}${d!=null&&s.dailyChange==null?'<span class="subcell">Diferença simples, não conciliada</span>':''}</td><td>${esc(s.source||s.origin||'Manual')}<span class="subcell">${esc(snapshotLabels[s.status]||s.status||'Manual')}</span></td><td class="small">${esc(s.notes||s.reconciliation||'')}</td></tr>`}).join('')||'<tr><td colspan="6" class="empty">Ainda não há snapshots registrados.</td></tr>'}</tbody></table></div></div>${renderMissingDaily()}<div class="small" style="margin-top:12px">${state.snapshots.length} registros de patrimônio preservados. Pontos sem dados de preço individual ou fluxos permanecem sem conciliação.</div>`}
  function renderAnalysis(){return `${pageHead('Análise de ativos','Registre fundamentos, relatórios e notícias com fonte e período.',`<button class="btn btn-outline" data-action="quote">＋ Registrar cotação</button><button class="btn btn-primary" data-action="research">＋ Registrar dado</button>`)}${notice('Não há integração automática de cotações, fundamentos ou notícias configurada. O Investidor10 é referência para conferência manual; não é acessado por scraping.','info')}<div class="card table-card"><div class="table-top"><div><b class="section-title">Ativos e saúde financeira</b><div class="small">Dados externos devem incluir fonte, URL, data de consulta e período de referência.</div></div></div><div class="table-wrap"><table><thead><tr><th>Ativo</th><th>Tipo</th><th>Cotação conhecida</th><th>Fundamentos / relatórios</th><th>Ação</th></tr></thead><tbody>${state.assets.map(a=>{const records=(state.research||[]).filter(r=>r.ticker===a.ticker);return `<tr><td class="ticker">${esc(a.ticker)}</td><td>${esc(a.asset_type)}</td><td>${a.quote?`${fmt(a.quote.price)}<span class="subcell">${esc(a.quote.source)} · ${date(a.quote.referenceDate)} · ${a.quote.status==='user_reported_screenshot'?'Informado no print':'informado manualmente'}</span>`:'Não disponível'}</td><td>${records.length?`${records.length} registro(s)<span class="subcell">${esc(records.at(-1).title)}</span>`:'<span class="status">Precisa de confirmação</span>'}</td><td><button class="btn btn-light" data-action="edit-asset" data-id="${esc(a.id)}">Detalhes</button><button class="btn btn-outline" data-action="research" data-id="${esc(a.id)}">＋</button></td></tr>`}).join('')||'<tr><td colspan="5" class="empty">Importe ativos para começar.</td></tr>'}</tbody></table></div></div><div class="card table-card" style="margin-top:16px"><div class="table-top"><div><b class="section-title">Registros rastreáveis</b><div class="small">Separação de fato informado, interpretação e notícia.</div></div></div>${(state.research||[]).slice().reverse().map(r=>{const href=safeUrl(r.source_url);return `<div class="ref-item"><b>${esc(r.ticker)} · ${esc(r.title)}</b> <span class="pill">${esc(r.kindLabel)}</span> <span class="pill">${esc(r.recordType)}</span><div class="detail">${esc(r.value||'Não disponível')} · período ${esc(r.period||'não informado')}<br>${esc(r.source)} · consultado em ${date(r.retrievedAt?.slice(0,10))}${href?` · <a href="${esc(href)}" target="_blank" rel="noopener">Abrir fonte</a>`:''}</div></div>`}).join('')||'<div class="empty">Nenhum fundamento, relatório ou notícia registrado.</div>'}</div><div class="card" style="margin-top:16px"><h2 class="section-title">Como interpretar</h2><p class="detail">Pontos positivos, alertas e riscos são registros manuais vinculados à fonte e ao período. Não há pontuação automática nem conclusão inventada.</p></div>`}
  function renderDividends(){
    const months=[...new Set(state.dividends.map(d=>d.competence).filter(m=>/^\d{4}-\d{2}$/.test(String(m||''))))].sort().reverse();
    if(dividendMonth==='auto')dividendMonth=months.includes(today().slice(0,7))?today().slice(0,7):(months[0]||'all');
    if(dividendMonth!=='all'&&!months.includes(dividendMonth))dividendMonth=months[0]||'all';
    const selectedRows=state.dividends.filter(d=>dividendMonth==='all'||d.competence===dividendMonth);
    const received=selectedRows.filter(d=>d.status==='received'),forecasts=selectedRows.filter(d=>d.forecast!=null);
    const reportAggregate=selectedRows.find(d=>d.status==='user_reported_aggregate'&&d.received!=null),reportedLines=selectedRows.filter(d=>d.status==='user_reported_paid_screenshot'&&d.received!=null);
    const reportedLineTotal=total(reportedLines,'received'),reportedTotal=reportAggregate?.received??reportedLineTotal;
    const publicTotal=selectedRows.filter(d=>d.publicReference).reduce((n,d)=>n+Number(d.publicReference.entitlementAmount||0),0);
    const monthName=dividendMonth==='all'?'Todas as competências':dividendMonth;
    const monthOptions=months.map(m=>`<option value="${m}" ${dividendMonth===m?'selected':''}>${m}</option>`).join('');
    return `${pageHead('Proventos','Consulte os eventos por competência, posição elegível e valores efetivamente informados.',`<button class="btn btn-primary" data-action="add-dividend">＋ Registrar evento</button>`)}${notice('Valores públicos por cota são cruzados com as aquisições registradas até a data-com. Recebimentos de captura, agregados, cálculos públicos e confirmações do usuário permanecem separados.','info')}<div class="card table-card"><div class="table-top"><div><b class="section-title">Visualizar competência</b><div class="small">Selecione o mês para filtrar os eventos e os totais abaixo.</div></div><label class="field-inline">Mês <select id="dividend-month"><option value="all" ${dividendMonth==='all'?'selected':''}>Todas</option>${monthOptions}</select></label></div></div><div class="grid metrics" style="margin-top:14px"><div class="card"><div class="metric-label">Recebido e confirmado · ${esc(monthName)}</div><div class="metric-value">${fmt(total(received,'received'))}</div><div class="metric-foot">${received.length} evento(s) confirmados pelo usuário.</div></div><div class="card"><div class="metric-label">Total mensal informado na fonte</div><div class="metric-value">${fmt(reportAggregate?reportedTotal:null)}</div><div class="metric-foot">Agregado exibido no Investidor10/print; não convertido em confirmação.</div></div><div class="card"><div class="metric-label">Soma das linhas informadas</div><div class="metric-value">${fmt(reportedLines.length?reportedLineTotal:null)}</div><div class="metric-foot">${reportedLines.length} eventos individuais reportados; não somar novamente ao agregado.</div></div><div class="card"><div class="metric-label">Elegibilidade calculada com fonte pública</div><div class="metric-value">${selectedRows.some(d=>d.publicReference)?fmt(publicTotal):'Não disponível'}</div><div class="metric-foot">${selectedRows.filter(d=>d.publicReference).length} evento(s) com valor público e quantidade elegível. JCP calculado pelo valor bruto.</div></div></div><div class="grid metrics" style="margin-top:14px"><div class="card"><div class="metric-label">Referências de previsão históricas · ${esc(monthName)}</div><div class="metric-value">${fmt(total(forecasts,'forecast'))}</div><div class="metric-foot">Registros importados mantidos à parte; não equivalem a pagamentos do mês confirmados.</div></div><div class="card"><div class="metric-label">Meta mensal</div><div class="metric-value">${fmt(state.settings.goals?.[1]||50)}</div><div class="metric-foot">Progresso depende de recebimentos confirmados.</div></div></div><div class="card table-card"><div class="table-top"><div><b class="section-title">Eventos, recebimentos e cálculo de elegibilidade</b><div class="small">Quantidade elegível pelas posições e compras registradas até a data-com.</div></div></div><div class="table-wrap"><table><thead><tr><th>Competência / datas</th><th>Ativo / posição elegível</th><th>Valor público por unidade</th><th>Valor calculado elegível</th><th>Recebido registrado</th><th>Status / divergências</th><th>Fonte</th><th>Ação</th></tr></thead><tbody>${selectedRows.map(d=>{const ref=d.publicReference,href=safeUrl(ref?.url);return `<tr><td>${esc(d.competence)}${ref?`<span class="subcell">Data-com ${date(ref.exDate)} · pagamento ${date(ref.paymentDate)}</span>`:''}</td><td>${esc(d.ticker||'Referência importada')}${ref?`<span class="subcell">${num(ref.eligibleQuantity,4)} cotas elegíveis</span>`:`<span class="subcell">${d.unitValue!=null?`${fmt(d.unitValue)} por unidade`:esc(d.note||'Valor agregado')}</span>`}</td><td>${ref?`${fmtUnit(ref.unitValue)}<span class="subcell">${esc(ref.kind)} · Investidor10</span>`:'—'}</td><td>${ref?`${fmt(ref.entitlementAmount)}<span class="subcell">${num(ref.eligibleQuantity,4)} × ${fmtUnit(ref.unitValue)}</span>`:(d.forecast==null?'—':fmt(d.forecast))}</td><td>${d.received==null?'—':fmt(d.received)}${d.status==='user_reported_paid_screenshot'?'<span class="subcell">Informado no print, não confirmado no app.</span>':''}</td><td><span class="status ${d.status==='received'?'ok':''}">${esc(d.statusLabel||d.status)}</span>${ref?.differenceNote?`<span class="subcell">${esc(ref.differenceNote)}</span>`:''}</td><td>${href?`<a href="${esc(href)}" target="_blank" rel="noopener">Investidor10</a>`:esc(d.source||'Não informada')}<span class="subcell">Consultado em ${ref?date(ref.retrievedAt?.slice(0,10)):'—'}</span></td><td>${d.status==='received'?'<span class="small">Confirmado</span>':`<button class="btn btn-light" data-action="confirm-dividend" data-id="${esc(d.id)}">Confirmar recebimento</button>`}</td></tr>`}).join('')||'<tr><td colspan="8" class="empty">Nenhum evento nessa competência.</td></tr>'}</tbody></table></div></div>`}
  function renderPlanner(){const month=today().slice(0,7),b=planBudget(month),p=state.plans.find(x=>x.month===month),sum=p?.items?.length&&p.items.every(x=>x.price!=null)?total(p.items.map(x=>({total:x.price*x.quantity})),'total'):null;return `${pageHead('Planejamento de aportes','Planeje quantidades sem registrar compras como realizadas.',`<button class="btn btn-outline" data-action="new-plan">Salvar plano</button><button class="btn btn-outline" data-action="realize-plan">Confirmar compras realizadas</button><button class="btn btn-primary" data-action="simulate">＋ Simular compra</button>`)}${state.pendingPlan?notice(`<strong>Plano de outubro/2026 aguardando confirmação:</strong> a referência sugeria IVVB11 (1), BTCI11 (14), VISC11 (1) e BTLG11 (1), total histórico ${fmt(state.pendingPlan.reference_purchase_total_brl)} em 30/09/2026. Nenhuma quantidade foi adicionada às posições. <button class="btn btn-light" data-action="confirm-old-plan">Confirmar execução</button>`):''}<div class="grid metrics"><div class="card"><div class="metric-label">Contribuição fixa-base</div><div class="metric-value">${fmt(b.base)}</div><div class="metric-foot">Configurada pelo backup</div></div><div class="card"><div class="metric-label">Proventos elegíveis</div><div class="metric-value">${fmt(b.dividends)}</div><div class="metric-foot">Recebidos no mês anterior e destinados.</div></div><div class="card"><div class="metric-label">Sobra acumulada</div><div class="metric-value">${fmt(b.surplus)}</div><div class="metric-foot">Saldo final do plano anterior.</div></div><div class="card"><div class="metric-label">Orçamento de planejamento · ${month}</div><div class="metric-value">${fmt(b.total)}</div><div class="metric-foot">Compras simuladas: ${fmt(sum)} · sobra estimada: ${sum==null?'Não disponível':fmt(Math.max(0,b.total-sum))}</div></div></div><div class="grid two-col"><div class="card"><div class="card-heading"><div><h2>Simulador de compras</h2><p>Preço manual com fonte e data; nunca envia ordens.</p></div></div><div class="small">Selecione um ativo e informe unidades. Sem cotação confirmada, não é possível calcular o total da simulação. Taxas só serão consideradas se configuradas.</div><button class="btn btn-primary" style="margin-top:15px" data-action="simulate">＋ Adicionar item à simulação</button><div id="plan-lines">${p?.items?.length?p.items.map(x=>`<div class="ref-item">${esc(x.ticker)} · ${x.quantity} un. · ${x.price==null?'cotação não informada':fmt(x.quantity*x.price)} <button data-action="remove-plan-item" data-id="${esc(x.id)}" class="btn btn-light">Remover</button></div>`).join(''):'<div class="empty">Nenhum ativo simulado.</div>'}</div>${sum!=null&&sum>b.total?notice('<strong>A simulação ultrapassa o orçamento projetado.</strong> Reduza as quantidades antes de validar.'):''}</div><div class="card"><div class="card-heading"><div><h2>Disponibilidade</h2><p>Valores planejados e confirmados permanecem separados.</p></div></div><div class="ref-item">Dinheiro disponível confirmado <b style="float:right">${p?.confirmedCash?fmt(p.confirmedCash):'Não informado'}</b></div><div class="ref-item">Orçamento projetado <b style="float:right">${fmt(b.total)}</b></div><div class="ref-item">Cotação total simulada <b style="float:right">${fmt(sum)}</b></div><div class="ref-item">Sobra depois das compras simuladas <b style="float:right">${sum==null?'Não disponível':fmt(Math.max(0,b.total-sum))}</b></div><p class="small">O orçamento não equivale a saldo bancário. Proventos previstos não contam como caixa confirmado. Marcar realizado exige confirmação expressa e registra transações.</p></div></div>`}
  function renderHistory(){return `${pageHead('Histórico','Referências históricas importadas não são automaticamente saldos atuais.',`<button class="btn btn-outline" data-action="export-csv">↓ Exportar CSV</button><button class="btn btn-primary" data-action="monthly-report">Gerar relatório</button>`)}<div class="grid two-col"><div class="card"><div class="card-heading"><div><h2>Snapshots agregados antigos</h2><p>Data exata não identificada; referência apenas.</p></div></div>${state.historicalSnapshots.map(s=>`<div class="ref-item"><b>${esc(s.snapshot_label||s.title||s.date||'Alocação histórica')}</b><div class="small">Patrimônio referido: ${fmt(s.total_portfolio_value_brl)} · Investido: ${fmt(s.total_invested_brl)} · Rentabilidade reportada: ${num(s.reported_return_pct)}%<br>${esc(s.status)} · ${esc(s.notes||'data não confirmada')}</div></div>`).join('')||'<div class="empty">Nenhuma referência agregada.</div>'}</div><div class="card"><div class="card-heading"><div><h2>Saldos de renda fixa históricos</h2><p>Referências históricas; confirmar saldos atuais.</p></div></div>${state.fixedIncome.map(x=>`<div class="ref-item"><b>${esc(x.label)}</b><div class="small">${fmt(x.reported_balance_brl??x.amount_brl)} · ${date(x.reference_date)} · ${esc(x.status)} · não é saldo atual confirmado</div><button class="btn btn-outline" data-action="confirm-balance" data-id="${esc(x.label)}" style="margin-top:8px">Confirmar saldo atual</button></div>`).join('')||'<div class="empty">Nenhuma referência.</div>'}</div></div><div class="card table-card" style="margin-top:16px"><div class="table-top"><div><b class="section-title">Planos e revisões mensais</b><div class="small">Planejado não é realizado; dados ausentes não aparecem como zero.</div></div></div><div class="table-wrap"><table><thead><tr><th>Mês</th><th>Orçamento</th><th>Compras planejadas</th><th>Compras realizadas</th><th>Sobra confirmada</th><th>Status</th><th></th></tr></thead><tbody>${state.plans.map(p=>`<tr><td>${esc(p.month)}</td><td>${fmt(p.budget)}</td><td>${fmt(p.proposedPurchasesTotal??null)}</td><td>${fmt(p.realizedTotal??null)}</td><td>${fmt(p.surplusFinal??null)}</td><td><span class="status ${p.status==='realizado'?'ok':''}">${esc(p.status)}</span></td><td><button class="btn btn-light" data-action="monthly-report" data-id="${esc(p.month)}">Relatório</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">Nenhum fechamento mensal salvo.</td></tr>'}</tbody></table></div></div>${renderImportedRules()}${renderPositionHistory()}<div class="grid two-col" style="margin-top:16px"><div class="card"><h2 class="section-title">Alocações históricas</h2>${(state.portfolioAllocationSnapshots||[]).map(x=>`<div class="ref-item"><b>${esc(x.date||'Data não informada')}</b> · ${esc(x.status)}<div class="small">${Object.entries(x.percentages||{}).map(([k,v])=>`${esc(k)} ${num(v)}%`).join(' · ')}<br>${esc(x.notes||'')}</div></div>`).join('')||'<div class="empty">Nenhuma alocação histórica importada.</div>'}${(state.withinClassWeights||[]).map(x=>`<div class="ref-item"><b>Pesos antigos dentro da classe</b> · ${esc(x.status)}<div class="small">${Object.entries(x.fiis||{}).map(([k,v])=>`${esc(k)} ${num(v)}%`).join(' · ')}<br>${Object.entries(x.stocks||{}).map(([k,v])=>`${esc(k)} ${num(v)}%`).join(' · ')}</div></div>`).join('')}</div><div class="card"><h2 class="section-title">Impacto diário estimado</h2>${(state.dailyAssetImpacts||[]).map(x=>`<div class="ref-item"><b>${date(x.date)} · ${esc(x.status)}</b><div class="small">Variação do patrimônio: ${fmt(x.portfolio_change_brl)} · soma estimada dos ativos: ${fmt(x.estimated_sum_brl)} · diferença não conciliada: ${fmt(x.unreconciled_difference_brl)}</div><div class="small">${Object.entries(x.asset_impacts_brl||{}).map(([k,v])=>`${esc(k)} ${fmt(v)}`).join(' · ')}</div></div>`).join('')||'<div class="empty">Nenhuma estimativa de impacto.</div>'}</div></div>`}
  function renderPositionHistory(){return `<div class="card table-card" style="margin-top:16px"><div class="table-top"><div><b class="section-title">Posições históricas</b><div class="small">Quantidades anteriores e posteriores às compras de outubro; a data-base anterior é indicada pelo rótulo da fonte.</div></div></div><div class="table-wrap"><table><thead><tr><th>Período</th><th>Data indicada</th><th>Ativo</th><th>Classe</th><th>Quantidade</th><th>Status</th></tr></thead><tbody>${(state.positionHistory||[]).map(x=>`<tr><td>${esc(x.periodLabel)}</td><td>${date(x.as_of)}</td><td class="ticker">${esc(x.ticker)}</td><td>${esc(labels[x.asset_class]||x.asset_class)}</td><td>${num(x.quantity,0)}</td><td>${esc(x.status)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Nenhuma posição histórica.</td></tr>'}</tbody></table></div></div>`}
  function renderImportedRules(){return `<div class="card" style="margin-top:16px"><h2 class="section-title">Regras históricas importadas</h2>${(state.importedRules||[]).map(x=>`<div class="ref-item"><b>Moeda ${esc(x.currency)} · fuso ${esc(x.timezone)}</b><div class="small">Meta patrimônio: ${fmt(x.goals?.primary_portfolio_target_brl)} · meta proventos: ${fmt(x.goals?.secondary_monthly_proventos_target_brl)}<br>Aporte: ${esc(x.rules?.monthly_contribution)}<br>Fins de semana/feriados: ${esc(x.rules?.weekends_and_market_holidays)}<br>Análise diária: ${esc(x.rules?.daily_analysis)}<br>Preferência de preço: ${esc(x.rules?.price_preference)}<br>Nota de desempenho: ${esc(x.rules?.performance_warning)}</div></div>`).join('')||'<div class="empty">Nenhuma regra histórica importada.</div>'}</div>`}
  function renderSources(){return `${pageHead('Fontes e configurações','Ajuste metas e contribuição. Consulte o histórico de dados importados e manuais.',`<button class="btn btn-primary" data-action="import">Importar backup</button>`)}${notice('Não há API de mercado conectada. Esta versão oferece cadastro manual rastreável e importação/exportação local. Nenhum valor externo é consultado automaticamente.','info')}<div class="grid two-col"><div class="card"><div class="card-heading"><div><h2>Preferências</h2><p>Aplicadas aos novos planejamentos.</p></div></div><div class="field"><label for="base-contribution">Contribuição mensal fixa-base (R$)</label><input id="base-contribution" type="number" min="0" step="0.01" value="${esc(state.settings.monthlyBase)}"></div><div class="field"><label for="goal-value">Meta prioritária de patrimônio (R$)</label><input id="goal-value" type="number" min="0" step="0.01" value="${esc(state.settings.goals?.[0]||10000)}"></div><div class="field"><label for="goal-dividend">Meta secundária de proventos mensais (R$)</label><input id="goal-dividend" type="number" min="0" step="0.01" value="${esc(state.settings.goals?.[1]||50)}"></div><div class="field"><label>Fuso horário</label><input value="${esc(state.settings.timezone||'America/Maceio')}" disabled></div><button class="btn btn-primary" data-action="save-settings">Salvar preferências</button></div><div class="card"><div class="card-heading"><div><h2>Importação e backups</h2><p>Importação parcial idempotente; não remove itens ausentes no arquivo.</p></div></div><p class="detail">A última importação reconhece schema_version, preserva valores null como ausentes e não aplica planos de compra pendentes.</p><div class="ref-item">Arquivo importado: ${state.importedFiles.map(esc).join(', ')||'nenhum registrado'}</div><div class="actions" style="margin-top:14px"><button class="btn btn-outline" data-action="import">Importar JSON</button><button class="btn btn-primary" data-action="export">Exportar backup completo</button></div><p class="small">Os dados são compartilhados entre navegadores deste computador pelo servidor local; o localStorage é uma cópia auxiliar. Exporte backups para recuperar ou levar os dados a outro dispositivo.</p></div></div><div class="card" style="margin-top:16px"><div class="card-heading"><div><h2>Histórico de fontes</h2><p>Consultas e importações rastreadas.</p></div></div>${state.sourceLogs.slice().reverse().map(l=>`<div class="ref-item"><b>${esc(l.provider)}</b> · ${esc(l.status)}<div class="small">${new Date(l.at).toLocaleString('pt-BR',{timeZone:'America/Maceio'})} · ${esc(l.url)} · ${esc(l.detail||'')}</div></div>`).join('')||'<div class="empty">Nenhuma consulta registrada.</div>'}</div><div class="card" style="margin-top:16px"><div class="card-heading"><div><h2>Relatórios de importação</h2><p>Contagens por tipo e pendências de conciliação.</p></div></div>${(state.importReports||[]).slice().reverse().map(r=>`<div class="ref-item"><b>${esc(r.file)}</b> · ${new Date(r.importedAt).toLocaleString('pt-BR',{timeZone:state.settings.timezone||'America/Maceio'})}<div class="small">Total: ${r.importedTotal||0} registros importados / ${r.duplicatesTotal||0} equivalências ignoradas<br>Snapshots: ${r.snapshots?.imported||0} / ${r.snapshots?.duplicates||0} · Transações: ${r.transactions?.imported||0} / ${r.transactions?.duplicates||0} · Saldos: ${r.fixedIncome?.imported||0} / ${r.fixedIncome?.duplicates||0} · Proventos: ${r.dividends?.imported||0} / ${r.dividends?.duplicates||0}<br>Posições históricas: ${r.historicalPositions?.imported||0} / ${r.historicalPositions?.duplicates||0} · Regras: ${r.rules?.imported||0} / ${r.rules?.duplicates||0} · Planos: ${r.plans?.imported||0} / ${r.plans?.duplicates||0} · Alocações: ${r.allocations?.imported||0} / ${r.allocations?.duplicates||0} · Contribuições/estimativas: ${r.contributionRecords?.imported||0} / ${r.contributionRecords?.duplicates||0}<br>Posições ajustadas: ${(r.positionAdjustments||[]).filter(x=>x.from!==x.to).length} · conflitos: ${(r.conflicts||[]).length} · inconsistências aritméticas: ${(r.inconsistencies||[]).length} · observações divergentes/arredondamento: ${(r.observations||[]).length} · confirmações pendentes: ${(r.confirmations||[]).length}</div>${[...(r.conflicts||[]),...(r.inconsistencies||[]),...(r.observations||[]),...(r.confirmations||[])].map(x=>`<div class="small">• ${esc(x)}</div>`).join('')}</div>`).join('')||'<div class="empty">Nenhuma importação de histórico.</div>'}</div>`}
  function render(){let key=location.hash.slice(1)||'dashboard';if(!pageNames[key])key='dashboard';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===key));document.getElementById('crumb').textContent=pageNames[key];if(activeUser){const profileButton=document.getElementById('profile-button');profileButton.textContent=activeUser.name.slice(0,1).toLocaleUpperCase('pt-BR');profileButton.title=`Perfil: ${activeUser.name} · trocar perfil`;}const funcs={dashboard:renderDashboard,portfolio:renderPortfolio,daily:renderDaily,analysis:renderAnalysis,dividends:renderDividends,planner:renderPlanner,history:renderHistory,sources:renderSources};document.getElementById('app').innerHTML=funcs[key]();document.title=`${pageNames[key]} · Carteira`;}
  function toast(s){const t=document.getElementById('toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2600)}
  function dialog(title,html,submit,submitText='Salvar'){const d=document.getElementById('dialog');d.className='dialog';d.innerHTML=`<form method="dialog" class="dialog-inner"><h2>${title}</h2>${html}<div class="dialog-actions"><button type="button" class="btn btn-light" data-close>Cancelar</button><button type="submit" class="btn btn-primary">${submitText}</button></div></form>`;d.querySelector('[data-close]').onclick=()=>d.close();d.querySelector('form').onsubmit=e=>{e.preventDefault();try{if(submit(new FormData(e.target))!==false){d.close();render()}}catch(err){toast(err.message)}};d.showModal()}
  function formField(label,name,type='text',value='',attrs=''){return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${attrs}></div>`}
  function importPreview(data){if(data.dataset==='historico_patrimonio_outubro_2026_desde_18'){const records=data.daily_records||[],holdings=data.portfolio_snapshot_2026_10_22?.holdings||[],missing=records.filter(x=>x.record_type==='missing'||x.patrimonio_total==null).length,weekend=records.filter(x=>x.record_type==='weekend_neutral').length;return `<p class="detail">Histórico diário até 22/10/2026 · fonte informada no arquivo: captura/relato do usuário. A importação é idempotente e preserva as quantidades atuais.</p><div class="ref-item"><b>Patrimônio diário</b><div class="small">${records.length} dias · ${records.length-missing} com valor e ${missing} sem fechamento. ${weekend} ponto(s) neutro(s) de fim de semana; nenhum valor será interpolado.</div></div><div class="ref-item"><b>Carteira e renda fixa</b><div class="small">${holdings.length} linhas de posições/saldos para referência de 22/10. Preços serão identificados como reportados em captura; saldos de renda fixa não serão marcados como confirmação independente.</div></div><div class="ref-item"><b>Proventos</b><div class="small">${(data.proventos_october_2026?.items||[]).length} linhas pagas informadas e total agregado de ${fmt(data.proventos_october_2026?.total_displayed_brl??null)}. A diferença de valores, se houver, será preservada.</div></div><p class="small">Regras de aporte serão guardadas como referências importadas. Não serão registradas compras nem proventos como confirmados apenas com base neste arquivo.</p>`}if(data.record_type==='market_capture'){const known=new Set(state.assets.map(a=>a.ticker.toUpperCase())),present=data.positions.filter(p=>known.has(String(p.ticker).toUpperCase())).length,captured=new Date(data.retrieved_at).toLocaleString('pt-BR',{timeZone:state.settings.timezone||'America/Maceio'});return `<p class="detail">Captura diária de <b>${esc(data.source_name)}</b> · referência ${date(data.reference_date)} (data da página não visível) · recebida em ${captured}.</p><div class="ref-item"><b>Valores transcritos</b><div class="small">${data.positions.length} posições; ${present} ticker(s) já existem. Serão guardados custo médio, preço exibido, quantidade, saldo mostrado e proventos recebidos acumulados quando visíveis. Quantidades e eventos de provento não serão alterados.</div></div><div class="ref-item"><b>Renda fixa</b><div class="small">${esc(data.fixed_income?.asset||'Não informada')} · aplicado ${fmt(data.fixed_income?.invested_brl??null)} · saldo exibido ${fmt(data.fixed_income?.balance_brl??null)}. Será anotado como valor informado no print, sem confirmar saldo atual.</div></div><div class="ref-item"><b>Conferência</b><div class="small">A soma das linhas de FIIs e ETFs será comparada aos subtotais visíveis. A referência da cotação usa a data de captura por não haver data legível na tela. O total geral do patrimônio não aparece e não será inventado.</div></div><p class="small">A captura será acrescentada ao acompanhamento diário; novas importações do mesmo registro não criarão cotações duplicadas.</p>`}let positions=data.positions_as_of_2026_09_11||data.assets||[];if(!positions.length&&data.holdings?.['before_2026-10-02']){positions=Object.entries(data.holdings['before_2026-10-02']).flatMap(([group,rows])=>Object.entries(rows||{}).map(([ticker,quantity])=>({ticker,quantity,asset_class:group==='stocks'?'equities':group}))) }const classes={};positions.forEach(p=>{const c=p.asset_class||'other';classes[c]=(classes[c]||0)+1});const known=new Set(state.assets.map(a=>a.ticker.toUpperCase()));const duplicate=positions.filter(p=>known.has(String(p.ticker).toUpperCase())).length;const isHistory=Array.isArray(data.patrimonio_history);const histDates=isHistory?data.patrimonio_history:[];const txs=data.transactions||[];const oldStatusCount=histDates.filter(s=>String(s.status).startsWith('raw_')||String(s.status).startsWith('weekend_')).length;const historicalRows=isHistory?(data.fixed_income_balances||[]):(data.fixed_income_balance_references||data.fixedIncome||[]);return `<p class="detail">Arquivo <b>${esc(data.title||data.backup_type||'backup de posições')}</b> · schema ${esc(data.schema_version)} · ${positions.length} posições. ${duplicate} ticker(s) já existem; serão conciliados sem somar quantidades repetidas.</p><div class="ref-item"><b>Posições por classe</b><div class="small">${Object.entries(classes).map(([k,v])=>`${esc(labels[k]||k)}: ${v}`).join(' · ')||'Nenhuma posição'}</div></div><div class="ref-item"><b>Tickers e quantidades-base</b><div class="small">${positions.map(p=>`${esc(p.ticker)} (${num(p.quantity,0)})`).join(' · ')||'Nenhuma posição'}</div></div>${isHistory?`<div class="ref-item"><b>Conteúdo histórico que será mapeado</b><div class="small">${histDates.length} snapshots (inclui ${oldStatusCount} pontos brutos/neutros) · ${txs.length} transações · ${historicalRows.length} saldos de renda fixa · ${(data.proventos?.monthly||[]).length+(data.proventos?.items||[]).length} registros de proventos · ${(data.contribution_history||[]).length} regras/fechamentos mensais · ${(data.portfolio_allocation_snapshots||[]).length} alocações · ${(data.daily_asset_impact_estimate||[]).length} estimativas de impacto.</div></div><div class="ref-item"><b>Reconciliação de posição</b><div class="small">Compras confirmadas de 02/10 só serão aplicadas se a quantidade local ainda corresponder ao saldo anterior do arquivo. Quantidades conflitantes serão preservadas e reportadas.</div></div>`:`<div class="ref-item"><b>Referências históricas</b><div class="small">${historicalRows.length} saldos antigos · ${(data.historical_aggregate_snapshots||data.historicalSnapshots||[]).length} snapshots agregados sem data confirmada</div></div>`}<div class="ref-item"><b>Pendências</b><div class="small">Estimativas e observações brutas continuam com seus status originais; valores ausentes não serão preenchidos. ${data.october_contribution_plan?'O plano executado será conciliado pelas transações confirmadas, não como compras adicionais.':''}</div></div><p class="small">A importação é idempotente e anexará os registros. Não remove nem substitui registros locais diferentes.</p>`}
  function assetDialog(a){const editing=!!a;dialog(editing?`Ativo ${esc(a.ticker)}`:'Adicionar posição',`${formField('Ticker','ticker','text',a?.ticker||'','required maxlength="15"')}${formField('Nome (opcional)','name','text',a?.name||'')}<div class="field"><label for="f-asset_class">Classe</label><select id="f-asset_class" name="asset_class"><option value="equities" ${a?.asset_class==='equities'?'selected':''}>Ações</option><option value="fiis" ${a?.asset_class==='fiis'?'selected':''}>FIIs</option><option value="etfs" ${a?.asset_class==='etfs'?'selected':''}>ETFs</option><option value="cash_or_fixed_income" ${a?.asset_class==='cash_or_fixed_income'?'selected':''}>Renda fixa / caixinha</option><option value="treasury_direct" ${a?.asset_class==='treasury_direct'?'selected':''}>Tesouro Direto</option><option value="other" ${a?.asset_class==='other'?'selected':''}>Outros</option></select></div>${formField('Quantidade','quantity','number',a?.quantity??1,'min="0" step="0.000001" required')}${a?`<div class="small">Quantidade atual: ${num(a.quantity,0)}. Para manter o histórico de operações, registre compra ou venda em Movimentação.</div>`:''}<hr><div class="small">Cotação e custo médio não serão estimados. Registre uma cotação com fonte para calcular valor de mercado.</div><button type="button" class="btn btn-outline" data-action="quote" data-id="${esc(a?.id||'')}">Registrar cotação</button><button type="button" class="btn btn-outline" data-action="add-transaction" data-id="${esc(a?.id||'')}">Registrar compra/venda</button>`,f=>{const t=f.get('ticker').trim().toUpperCase(),q=Number(f.get('quantity'));if(!t||!Number.isFinite(q)||q<0)throw Error('Informe ticker e quantidade válidos.');if(!editing&&state.assets.some(x=>x.ticker.toUpperCase()===t))throw Error('Esse ticker já existe. Edite a posição existente.');if(editing){a.ticker=t;a.name=f.get('name')||t;a.quantity=q;a.asset_class=f.get('asset_class')}else state.assets.push({id:'asset-'+t,ticker:t,name:f.get('name')||t,quantity:q,asset_class:f.get('asset_class'),asset_type:f.get('asset_class')==='fiis'?'real_estate_fund':f.get('asset_class')==='etfs'?'etf':'stock',position_date:today(),data_status:'manual_unverified'});save();toast('Posição salva. Cotação segue sem confirmação.')});document.getElementById('dialog').querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{const action=b.dataset.action,id=b.dataset.id;document.getElementById('dialog').close();if(action==='quote')quoteDialog(state.assets.find(x=>x.id===id));if(action==='add-transaction')transactionDialog(state.assets.find(x=>x.id===id))})}
  function quoteDialog(a){dialog(`Registrar cotação${a?' · '+esc(a.ticker):''}`,`${a?'':`<div class="field"><label>Ativo</label><select name="asset" required>${state.assets.map(x=>`<option value="${esc(x.id)}">${esc(x.ticker)}</option>`).join('')}</select></div>`}${formField('Preço por unidade (R$)','price','number','','min="0.0001" step="0.0001" required')}${formField('Data de referência','referenceDate','date',today(),'required')}${formField('Fonte','source','text','Informado pelo usuário','required')}${formField('URL da fonte (opcional)','source_url','url','')}${formField('Método','method','text','Conferência manual')}`,f=>{const asset=a||state.assets.find(x=>x.id===f.get('asset')),price=Number(f.get('price'));if(!asset||!Number.isFinite(price)||price<=0)throw Error('Preço deve ser maior que zero.');const quote={id:crypto.randomUUID(),ticker:asset.ticker,price,referenceDate:f.get('referenceDate'),source:f.get('source'),source_url:f.get('source_url')||null,method:f.get('method'),retrieved_at:new Date().toISOString(),currency:'BRL',status:'manual_user_entry'};state.quotes.push(quote);asset.quote=quote;state.sourceLogs.push({provider:f.get('source'),url:f.get('source_url')||'manual',at:quote.retrieved_at,status:'Manual',detail:`Cotação informada para ${asset.ticker}: ${fmt(price)} em ${f.get('referenceDate')}`});save();toast(`Cotação de ${asset.ticker} salva com fonte e data.`)});}
  function researchDialog(asset){dialog('Registrar fundamento, relatório ou notícia',`${asset?'':`<div class="field"><label>Ativo</label><select name="asset">${state.assets.map(x=>`<option value="${esc(x.ticker)}">${esc(x.ticker)}</option>`).join('')}</select></div>`}<div class="field"><label>Tipo de registro</label><select name="kind"><option value="fundamental">Fundamento / indicador</option><option value="report">Relatório oficial</option><option value="news">Notícia</option></select></div>${formField('Título / indicador','title','text','','required')}${formField('Valor ou resumo','value','text','')}${formField('Período de referência','period','text','')}${formField('Data de consulta/publicação','retrievedAt','date',today(),'required')}${formField('Fonte / veículo','source','text','','required')}${formField('URL','source_url','url','')}${formField('Classificação','recordType','text','Fato informado')}`,f=>{const ticker=asset?.ticker||f.get('asset');if(!ticker)throw Error('Selecione um ativo.');const kind=f.get('kind');(state.research||=[]).push({id:crypto.randomUUID(),ticker,kind,kindLabel:{fundamental:'Fundamento',report:'Relatório',news:'Notícia'}[kind],title:f.get('title'),value:f.get('value')||null,period:f.get('period')||null,retrievedAt:f.get('retrievedAt'),source:f.get('source'),source_url:f.get('source_url')||null,recordType:f.get('recordType')||'Fato informado'});save();toast('Registro salvo com fonte e período.')})}
  function transactionDialog(a){dialog(`Registrar movimentação${a?' · '+esc(a.ticker):''}`,`${a?'':`<div class="field"><label>Ativo</label><select name="asset">${state.assets.map(x=>`<option value="${esc(x.id)}">${esc(x.ticker)}</option>`).join('')}</select></div>`}<div class="field"><label>Tipo</label><select name="type"><option value="buy">Compra confirmada</option><option value="sell">Venda confirmada</option><option value="bonus">Bonificação / evento corporativo</option></select></div>${formField('Quantidade','quantity','number','','min="0.000001" step="0.000001" required')}${formField('Preço por unidade (R$)','price','number','','min="0" step="0.0001"')}${formField('Taxas (R$)','fees','number','0','min="0" step="0.01"')}${formField('Data','date','date',today(),'required')}<div class="small">Só transações confirmadas alteram posição. O custo médio só é calculado quando as compras estão registradas de forma suficiente.</div>`,f=>{const asset=a||state.assets.find(x=>x.id===f.get('asset')),q=Number(f.get('quantity'));if(!asset||!q||q<0)throw Error('Informe ativo e quantidade válida.');const type=f.get('type');if(type==='sell'&&q>asset.quantity)throw Error('Venda excede a posição registrada.');asset.quantity+=type==='buy'||type==='bonus'?q:-q;state.transactions.push({id:crypto.randomUUID(),ticker:asset.ticker,type,quantity:q,price:f.get('price')?Number(f.get('price')):null,fees:Number(f.get('fees'))||0,date:f.get('date'),confirmed:true,source:'manual'});if(type==='buy'&&f.get('price'))asset.average_cost_brl=null;save();toast('Movimentação confirmada e posição atualizada.')})}
  function snapshotDialog(){dialog('Registrar patrimônio',`${formField('Data de referência','date','date',today(),'required')}${formField('Patrimônio total confirmado (R$)','total','number','','min="0" step="0.01" required')}<div class="field"><label>Origem</label><select name="origin"><option>Manual</option><option>Investidor10 (informado pelo usuário)</option><option>Importação</option></select></div>${formField('Saldo disponível confirmado (R$)','cash','number','','min="0" step="0.01"')}<div class="field"><label>Conciliação da variação</label><select name="reconciliation"><option value="Causa não conciliada com os dados disponíveis">Causa não conciliada com os dados disponíveis</option><option value="Aporte/resgate informado, componentes ainda não conciliados">Aporte/resgate informado, componentes ainda não conciliados</option><option value="Conciliação manual informada pelo usuário">Conciliação manual informada pelo usuário</option></select></div><div class="small">Registros de sábado ou domingo entram como pendentes e exigem confirmação para a série oficial.</div>`,f=>{const d=f.get('date'),v=Number(f.get('total'));if(!Number.isFinite(v)||v<0)throw Error('Informe patrimônio válido.');const weekend=PortfolioCore.isWeekend(d);if(weekend&&!confirm('Esta data é no fim de semana. Incluir explicitamente na série oficial?'))return false;state.snapshots.push({id:crypto.randomUUID(),date:d,total:v,cash:f.get('cash')?Number(f.get('cash')):null,origin:f.get('origin'),status:weekend?'weekend_explicitly_confirmed':'confirmed',reconciliation:f.get('reconciliation'),createdAt:new Date().toISOString()});state.sourceLogs.push({provider:f.get('origin'),url:'registro manual',at:new Date().toISOString(),status:'Registrado',detail:`Snapshot ${d}`});save();toast('Snapshot registrado.')})}
  function dividendDialog(){dialog('Registrar provento',`${formField('Ativo ou descrição','ticker','text','')}${formField('Competência (AAAA-MM)','competence','month',today().slice(0,7),'required')}${formField('Valor previsto/declarado (R$)','forecast','number','','min="0" step="0.01"')}${formField('Valor recebido (R$)','received','number','','min="0" step="0.01"')}${formField('Data de pagamento','payDate','date','')}${formField('Fonte','source','text','Informado pelo usuário','required')}${formField('URL da fonte','source_url','url','')}`,f=>{const received=f.get('received')?Number(f.get('received')):null,forecast=f.get('forecast')?Number(f.get('forecast')):null;if(received==null&&forecast==null)throw Error('Informe previsto ou recebido.');state.dividends.push({id:crypto.randomUUID(),ticker:f.get('ticker')||null,competence:f.get('competence'),forecast,received,status:received!=null?'received':'forecast',statusLabel:received!=null?'Recebido':'Previsto',destined:false,payDate:f.get('payDate')||null,source:f.get('source'),source_url:f.get('source_url')||null,retrieved_at:new Date().toISOString()});save();toast('Evento de provento salvo.')})}
  function simulateDialog(){const month=today().slice(0,7),existing=state.plans.find(p=>p.month===month),items=existing?.items||[];if(existing?.status==='executed_pending_close'){toast('Este mês já consta como executado no histórico; não será alterado por uma nova simulação.');return}if(!state.assets.length){toast('Importe ou adicione ativos primeiro.');return}dialog('Simular compra',`<div class="field"><label>Ativo</label><select name="asset">${state.assets.map(a=>`<option value="${esc(a.id)}">${esc(a.ticker)} · qtd. ${num(a.quantity,0)}${a.quote?` · ${fmt(a.quote.price)}`:' · cotação não informada'}</option>`).join('')}</select></div>${formField('Quantidade inteira','quantity','number','1','min="1" step="1" required')}<div class="small">Preço utilizado somente se já houver cotação manual confirmada. Esta ação altera apenas a simulação.</div>`,f=>{let a=state.assets.find(x=>x.id===f.get('asset')),q=Number(f.get('quantity'));if(!Number.isInteger(q)||q<1)throw Error('Use uma quantidade inteira positiva.');let p=state.plans.find(x=>x.month===month);if(!p){const b=planBudget(month);p={month,budget:b.total,confirmedCash:b.confirmedCash,items:[],status:'planejado'};state.plans.push(p)}p.items.push({id:crypto.randomUUID(),ticker:a.ticker,quantity:q,price:a.quote?.price??null});p.proposedPurchasesTotal=p.items.every(x=>x.price!=null)?total(p.items.map(x=>({v:x.quantity*x.price})),'v'):null;save();toast('Item adicionado à simulação, sem alterar a carteira.')})}
  function savePlan(){const m=today().slice(0,7),b=planBudget(m);let p=state.plans.find(x=>x.month===m);if(p?.status==='executed_pending_close'){toast('O plano deste mês foi importado como executado. Feche a sobra após conciliar os proventos.');return}if(!p){p={month:m,budget:b.total,confirmedCash:b.confirmedCash,items:[],status:'planejado'};state.plans.push(p)}p.budget=b.total;p.proposedPurchasesTotal=p.items?.every(x=>x.price!=null)?total(p.items.map(x=>({v:x.quantity*x.price})),'v'):null;p.surplusFinal=p.proposedPurchasesTotal==null?null:Math.max(0,p.budget-p.proposedPurchasesTotal);save();toast('Plano mensal salvo. Nenhuma compra foi realizada.');render()}
  function realizePlan(){const p=state.plans.find(x=>x.month===today().slice(0,7));if(p?.status==='executed_pending_close'){toast('As compras deste mês já foram importadas como executadas; elas não serão registradas novamente.');return}if(!p?.items?.length){toast('Adicione itens à simulação antes de validar.');return}dialog('Confirmar compras realizadas',`${notice('Informe somente o que foi realmente comprado. O sistema atualizará as posições e registrará as movimentações.')}<div class="field"><label>Data das compras</label><input type="date" name="date" value="${today()}" required></div>${p.items.map((x,i)=>`<div class="field"><label>${esc(x.ticker)} · simulado ${x.quantity}</label><input type="number" name="q${i}" min="0" step="1" value="${x.quantity}" required></div>`).join('')}<div class="small">A cotação simulada fica como referência. Preço de execução só será registrado se você informar depois nos detalhes da transação.</div>`,f=>{let totalSpent=0;for(let i=0;i<p.items.length;i++){const x=p.items[i],q=Number(f.get('q'+i));if(!Number.isInteger(q)||q<0)throw Error('Informe quantidades inteiras válidas.');if(!q)continue;const a=state.assets.find(z=>z.ticker===x.ticker);if(!a)throw Error(`Ativo ${x.ticker} não encontrado.`);a.quantity+=q;state.transactions.push({id:crypto.randomUUID(),ticker:x.ticker,type:'buy',quantity:q,price:x.price,date:f.get('date'),confirmed:true,source:'fechamento mensal confirmado'});if(x.price!=null)totalSpent+=q*x.price}p.realizedTotal=totalSpent;p.status='realizado';p.realizedAt=new Date().toISOString();p.surplusFinal=totalSpent?PortfolioCore.finalSurplus(p.budget,totalSpent):null;save();toast('Compras realizadas registradas e posições atualizadas.')},'Confirmar compras realizadas')}
  function confirmOldPlan(){const p=state.pendingPlan;if(!p)return;dialog('Confirmar compras de outubro/2026',`<div class="notice">Confirme apenas se as compras foram realizadas. As quantidades existentes não serão alteradas até você informar as quantidades efetivas.</div>${(p.planned_purchases||[]).map(x=>`<div class="field"><label>${esc(x.ticker)} · quantidade efetivamente comprada</label><input type="number" name="q-${esc(x.ticker)}" min="0" step="1" value="0"></div>`).join('')}<div class="small">A referência de preço é de 30/09/2026 e não será aplicada como cotação atual.</div>`,f=>{for(const x of p.planned_purchases||[]){const q=Number(f.get(`q-${x.ticker}`));if(q>0){const a=state.assets.find(a=>a.ticker===x.ticker);if(a){a.quantity+=q;state.transactions.push({id:crypto.randomUUID(),ticker:x.ticker,type:'buy',quantity:q,price:null,date:'2026-10-01',confirmed:true,source:'confirmação do plano histórico'});}}}state.pendingPlan=null;save();toast('Confirmação salva com quantidades informadas.')},'Confirmar execuções')}
  function confirmDividend(id){const d=state.dividends.find(x=>x.id===id);if(!d)return;dialog('Confirmar provento recebido',`${formField('Valor efetivamente recebido (R$)','amount','number',d.forecast??'','min="0" step="0.01" required')}<label><input type="checkbox" name="destined"> Destinar ao aporte mensal</label><p class="small">A confirmação atualiza esse evento existente. Ela não cria outro registro nem duplica o valor.</p>`,f=>{const amount=Number(f.get('amount'));if(amount<0||!Number.isFinite(amount))throw Error('Valor inválido.');d.received=amount;d.status='received';d.statusLabel='Recebido';d.destined=f.has('destined');d.confirmed_at=new Date().toISOString();save();toast('Provento confirmado sem duplicação.')})}
  function confirmBalance(id){const b=state.fixedIncome.find(x=>x.label===id);if(!b)return;dialog('Confirmar saldo atual',`${formField('Saldo atual confirmado (R$)','balance','number','','min="0" step="0.01" required')}${formField('Data de referência','date','date',today(),'required')}${formField('Fonte','source','text','Informado pelo usuário','required')}`,f=>{b.confirmed_balance_brl=Number(f.get('balance'));b.confirmed_date=f.get('date');b.confirmed_source=f.get('source');b.status='current_user_confirmed';save();toast('Saldo atual confirmado registrado.')})}
  function removePlanItem(id){const p=state.plans.find(x=>x.month===today().slice(0,7));if(!p)return;p.items=p.items.filter(x=>x.id!==id);p.proposedPurchasesTotal=p.items.length&&p.items.every(x=>x.price!=null)?total(p.items.map(x=>({v:x.quantity*x.price})),'v'):null;save();render()}
  function exportData(){const payload={...state,exported_at:new Date().toISOString(),timezone:state.settings.timezone,backup_type:'portfolio_full_backup'};download(`backup_carteira_${today()}.json`,JSON.stringify(payload,null,2),'application/json')}
  function download(name,content,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
  function exportCsv(){const rows=[['ticker','classe','quantidade','cotacao_brl','data_cotacao','fonte','custo_medio_brl','valor_mercado_brl'],...state.assets.map(a=>[a.ticker,a.asset_class,a.quantity,a.quote?.price??'',a.quote?.referenceDate??'',a.quote?.source??'',a.average_cost_brl??'',a.quote?a.quantity*a.quote.price:''])];download(`posicoes_${today()}.csv`,rows.map(r=>r.map(x=>`"${String(x).replaceAll('"','""')}"`).join(';')).join('\r\n'),'text/csv;charset=utf-8')}
  function report(month){const p=state.plans.find(x=>x.month===month)||null;const snaps=state.snapshots.filter(s=>s.date.startsWith(month)).sort((a,b)=>a.date.localeCompare(b.date));document.getElementById('app').innerHTML=`${pageHead(`Relatório mensal · ${esc(month)}`,'Revisão gerada a partir dos registros disponíveis.',`<button class="btn btn-primary no-print" onclick="window.print()">Imprimir / salvar em PDF</button><button class="btn btn-light no-print" onclick="location.hash='#history'">Voltar</button>`)}<div class="grid metrics"><div class="card"><div class="metric-label">Snapshots do mês</div><div class="metric-value">${snaps.length}</div></div><div class="card"><div class="metric-label">Patrimônio inicial</div><div class="metric-value">${snaps.length?fmt(snaps[0].total):'Não disponível'}</div></div><div class="card"><div class="metric-label">Patrimônio final</div><div class="metric-value">${snaps.length?fmt(snaps.at(-1).total):'Não disponível'}</div></div><div class="card"><div class="metric-label">Orçamento do plano</div><div class="metric-value">${p?fmt(p.budget):'Não disponível'}</div></div></div><div class="grid two-col"><div class="card"><h2 class="section-title">Patrimônio e variação</h2>${snaps.length>1?`<p class="detail">Variação registrada: ${fmt(snaps.at(-1).total-snaps[0].total)}. A causa não pode ser atribuída sem conciliação de preços, aportes, resgates e proventos.</p>`:'<p class="detail">Não há snapshots suficientes para comparar este mês.</p>'}</div><div class="card"><h2 class="section-title">Alocação e proventos</h2><p class="detail">${state.assets.length} ativos registrados; cotações manuais confirmadas: ${state.assets.filter(a=>a.quote).length}. Proventos recebidos no mês: ${fmt(total(state.dividends.filter(d=>d.competence===month&&d.status==='received'),'received'))}.</p></div></div><div class="card" style="margin-top:16px"><h2 class="section-title">Plano do aporte</h2><p class="detail">Status: ${esc(p?.status||'Não planejado')}. Compras simuladas: ${fmt(p?.proposedPurchasesTotal)}. Compras realizadas confirmadas: ${fmt(p?.realizedTotal)}. Sobra: ${fmt(p?.surplusFinal)}.</p><p class="small">Fontes: registros do usuário, arquivo de backup importado e fontes indicadas em cada cotação/evento.</p></div>`;window.scrollTo(0,0)}
  document.getElementById('profile-button').addEventListener('click',openProfileSwitcher);
  document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;switch(a){case 'snapshot':snapshotDialog();break;case 'add-asset':assetDialog();break;case 'edit-asset':assetDialog(state.assets.find(x=>x.id===id));break;case 'quote':quoteDialog(state.assets.find(x=>x.id===id));break;case 'research':researchDialog(state.assets.find(x=>x.id===id));break;case 'add-transaction':transactionDialog(state.assets.find(x=>x.id===id));break;case 'add-dividend':dividendDialog();break;case 'simulate':simulateDialog();break;case 'new-plan':savePlan();break;case 'realize-plan':realizePlan();break;case 'confirm-old-plan':confirmOldPlan();break;case 'confirm-dividend':confirmDividend(id);break;case 'delete-snapshot':if(confirm('Excluir este snapshot? O registro será removido do histórico.')){state.snapshots=state.snapshots.filter(x=>x.id!==id);save();render();toast('Snapshot excluído.')}break;case 'remove-plan-item':removePlanItem(id);break;case 'confirm-balance':confirmBalance(id);break;case 'import':document.getElementById('import-file').click();break;case 'export':case 'export-top':exportData();break;case 'export-csv':exportCsv();break;case 'monthly-report':report(id||today().slice(0,7));break;case 'save-settings':{const base=Number(document.getElementById('base-contribution').value),g=Number(document.getElementById('goal-value').value),d=Number(document.getElementById('goal-dividend').value);if(base<0||g<0||d<0){toast('Informe valores iguais ou maiores que zero.');break}state.settings.monthlyBase=base;state.settings.goals=[g,d];save();render();toast('Preferências salvas.');break}}});
  document.addEventListener('change',e=>{if(e.target.id==='asset-search'){const q=e.target.value.trim().toLowerCase();document.getElementById('asset-rows').innerHTML=assetRows(state.assets.filter(a=>a.ticker.toLowerCase().includes(q)||a.name.toLowerCase().includes(q)))}else if(e.target.id==='dashboard-period'){dashboardPeriod=e.target.value;render()}else if(e.target.id==='transaction-competence'){transactionCompetence=e.target.value;render()}else if(e.target.id==='dividend-month'){dividendMonth=e.target.value;render()}});
  document.getElementById('import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{const data=JSON.parse(await file.text());const positions=data.positions_as_of_2026_09_11||data.assets||Object.values(data.holdings?.['before_2026-10-02']||{}).some(Boolean),isMarketCapture=data.record_type==='market_capture'&&Array.isArray(data.positions),isRecentHistory=data.dataset==='historico_patrimonio_outubro_2026_desde_18'&&Array.isArray(data.daily_records);if((!isMarketCapture&&!isRecentHistory&&!Array.isArray(positions)&&!Array.isArray(data.patrimonio_history))||!data.schema_version)throw Error('Arquivo inválido: schema_version ou registros reconhecidos ausentes.');dialog('Prévia da importação',importPreview(data),()=>{const report=importBackup(data,file.name);if(report?.positions)toast(`${report.positions.imported} cotações registradas; ${report.positions.duplicates} já existiam; ${report.inconsistencies.length} divergências para conferir.`);else if(report?.snapshots)toast(`${report.importedTotal} registros importados; ${report.duplicatesTotal} equivalências/duplicatas ignoradas. Consulte o relatório em Fontes.`);else toast('Importação concluída sem duplicar posições.')},'Confirmar importação')}catch(err){toast(`Falha na importação: ${err.message}`)}finally{e.target.value=''}});
  window.addEventListener('hashchange',render);
  async function boot(){const status=document.getElementById('storage-status');if(status)status.textContent=window.FirebaseCloud?.enabled?'Sincronização em nuvem ativa':'Dados no servidor local';try{if(window.FirebaseCloud?.enabled){const session=await FirebaseCloud.session();if(session?.user){await activateUser(session.user);return}}else{const response=await fetch('/api/session');if(!response.ok)throw Error('Autenticação local indisponível.');const session=await response.json();if(session.authenticated&&session.user){await activateUser(session.user);return}}}catch(err){console.warn('Não foi possível consultar a sessão:',err)}renderLogin()}
  boot();
})();
